    """True if the schedule expr runs at the minute of the datetime when."""
    spec = _parse(expr)
    days_in_month = calendar.monthrange(when.year, when.month)[1]
    return bool(
        when.minute in spec.minutes
        and when.hour in spec.hours
        and when.month in spec.months
        and _day_ok(spec, when.date(), days_in_month)
    )


def next_run(expr, after):
    """The first run of expr strictly after the datetime after, or None."""
    spec = _parse(expr)
    try:
        start = after.replace(second=0, microsecond=0) + _ONE_MINUTE
    except OverflowError:
        return None
    try:
        limit = after + _SPAN
    except OverflowError:
        limit = dt.datetime.max

    year, month = start.year, start.month
    while (year, month) <= (limit.year, limit.month):
        if month in spec.months:
            days_in_month = calendar.monthrange(year, month)[1]
            first_day = start.day if (year, month) == (start.year, start.month) else 1
            for day in range(first_day, days_in_month + 1):
                if not _day_ok(spec, dt.date(year, month, day), days_in_month):
                    continue
                if (year, month, day) == (start.year, start.month, start.day):
                    time = _first_time(spec, start.hour, start.minute)
                else:
                    time = _first_time(spec, 0, 0)
                if time is None:
                    continue
                candidate = dt.datetime(year, month, day, time[0], time[1])
                return candidate if candidate <= limit else None
        month += 1
        if month > 12:
            month = 1
            year += 1
    return None
